import React from 'react';
import DOMPurify from 'dompurify';

export function CommentView({ comment }) {
  // DOMPurify를 사용하여 사용자 입력을 안전하게 처리하여 Stored XSS 방지
  return (
    <div className="comment">
      <h3>User said:</h3>
      <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(comment) }} />
    </div>
  );
}
```
한줄 요약: DOMPurify를 사용하여 사용자 입력을 안전하게 처리하여 Stored XSS를 방지했습니다.
